import os,re,json
from collections import Counter,deque
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def f2(I):
    H,W=len(I),len(I[0]); bg=Counter(v for r in I for v in r).most_common(1)[0][0]
    out=[r[:] for r in I]
    pos=[(x,y) for x in range(H) for y in range(W) if I[x][y]!=bg]
    for dx,dy in ((1,0),(0,1)):
        lst=sorted(pos,key=lambda p:(p[0]*dy+p[1]*dx))
        for a,b in zip(lst,lst[1:]):
            n=max(abs(b[0]-a[0]),abs(b[1]-a[1]))
            if n<=1: continue
            for t in range(1,n):
                c,d=a[0]+t*dx,a[1]+t*dy
                if 0<=c<H and 0<=d<W and I[c][d]==bg: out[c][d]=3
    return out
